import {num} from './core.mjs';
import {comparisonGroups,reportTrend,dailyTrend} from './analysis.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,s=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[s]));
const n=(v,d=0)=>num(v)?v.toLocaleString('en-US',{maximumFractionDigits:d,minimumFractionDigits:d}):'—';
const hrs=v=>num(v)?n(v/60,1):'—';
const date=s=>s?new Date(s+'T12:00:00Z').toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric',timeZone:'UTC'}):'Unavailable';
const colors=['#4f008c','#ff375e','#a7a0b2'];
function rate(v){return num(v)?`<span class="report-rate ${v<0?'good':v>0?'bad':''}">${v>0?'+':''}${n(v,1)}%</span>`:'<span class="muted">—</span>';}
function coverage(s){return !s.covered?'Outside source coverage':s.partial?'Partial source coverage':'Within source date range';}
function subtitle(report){return `${report.definition.impact==='NSA'?'Non-service affected · impact other than Outage':'Services affected · Outage'} · ${report.profile.name||'Report criteria'}`;}
function card(label,value,unit,change,reference,note,featured=false){return `<article class="kpi ${featured?'featured':''}"><div class="kpi-top"><span class="kpi-label">${esc(label)}</span><span class="report-card-dot"></span></div><div class="kpi-value">${value}${unit?`<small>${unit}</small>`:''}</div><div class="kpi-footer">${rate(change)}<span>${esc(reference)}</span></div><div class="kpi-note">${esc(note)}</div></article>`;}
function seriesHeader(report){return `<div class="report-series">${report.series.map((s,i)=>`<div class="report-series-item ${i===0?'current':''}"><span class="report-series-label"><i style="background:${colors[i]}"></i>${i===0?'Review period':i===1?'Comparison':'Earlier comparison'}</span><b>${esc(s.range?.label||'Week unavailable in this year')}</b><span>${s.range?date(s.range.start)+' – '+date(s.range.end):'Calendar has no matching week'}</span><small class="${s.partial?'partial':''}">${coverage(s)} · ${n(s.summary?.tickets)} tickets</small></div>`).join('')}</div>`;}
function trend(report,state,meta){
  const values=reportTrend(report,state,meta),w=880,h=245,l=46,r=60,t=22,b=45,pw=w-l-r,ph=h-t-b,gap=pw/12;
  const max=Math.max(1,...values.map(x=>x.summary?.tickets||0)),maxH=Math.max(1,...values.map(x=>(x.summary?.durationMinutes||0)/60));
  const nice=x=>{const v=10**Math.floor(Math.log10(x));return Math.ceil(x/v/2)*v*2;},yMax=Math.max(4,nice(max)),hMax=nice(maxH);
  let svg=`<svg class="trend-svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="Twelve-period trend: columns show ticket rows; pink line shows restoration hours."><text x="${l}" y="10">Tickets</text><text x="${w-r+9}" y="10">Hours</text>`;
  for(let i=0;i<=4;i++){const y=t+ph-i*ph/4;svg+=`<line x1="${l}" x2="${w-r}" y1="${y}" y2="${y}" stroke="#ece7f1" stroke-dasharray="3 4"/><text x="${l-9}" y="${y+3}" text-anchor="end">${n(yMax*i/4)}</text><text x="${w-r+10}" y="${y+3}">${n(hMax*i/4,Math.min(3,Math.max(0,1-Math.floor(Math.log10(hMax)))))}</text>`;}
  let points=[];const segments=[];
  values.forEach((x,i)=>{const cx=l+gap*(i+.5),tickets=x.summary?.tickets,mins=x.summary?.durationMinutes,y=t+ph-(tickets||0)/yMax*ph;
    svg+=`<rect x="${cx-gap*.23}" y="${y}" width="${gap*.46}" height="${t+ph-y}" rx="3" fill="${i===11?'#4f008c':'#decbe9'}"><title>${esc(x.range.label)}: ${num(tickets)?n(tickets)+' tickets, '+hrs(mins)+' hours':'outside source coverage'}${x.partial?' (partial)':''}</title></rect><text x="${cx}" y="${h-23}" text-anchor="middle">${esc(x.range.week?'W'+x.range.week:x.range.label.split(' ')[0])}</text><text x="${cx}" y="${h-9}" text-anchor="middle" style="font-size:8px">${x.range.year}</text>`;
    if(num(mins))points.push({x:cx,y:t+ph-mins/60/hMax*ph,label:x.range.label,mins});else if(points.length){segments.push(points);points=[];}
  });if(points.length)segments.push(points);
  for(const p of segments){svg+=`<polyline points="${p.map(v=>v.x+','+v.y).join(' ')}" fill="none" stroke="#ff375e" stroke-width="2.5"/>`;for(const x of p)svg+=`<circle cx="${x.x}" cy="${x.y}" r="3" fill="white" stroke="#ff375e" stroke-width="2"><title>${esc(x.label)}: ${hrs(x.mins)} hours</title></circle>`;}
  return `<section class="panel report-trend"><div class="panel-title"><div><h2>Performance trend</h2><p>Same page criteria across the last 12 ${report.definition.mode.includes('week')?'weeks':'months'}</p></div><div class="legend"><span><i></i>Tickets</span><span><i class="line"></i>Hours</span></div></div>${svg}</svg><details class="chart-data"><summary>View trend values</summary><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Period</th><th>Tickets</th><th>Restoration hrs</th><th>Coverage</th></tr></thead><tbody>${values.map(x=>`<tr><td>${esc(x.range.label)}</td><td>${n(x.summary?.tickets)}</td><td>${hrs(x.summary?.durationMinutes)}</td><td>${coverage(x)}</td></tr>`).join('')}</tbody></table></div></details></section>`;
}
function focus(report){
  const groups=comparisonGroups(report,'root_cause'),districts=comparisonGroups(report,'district'),top=groups[0],worst=[...groups].filter(g=>g.series[1]).sort((a,b)=>((b.series[0]?.durationMinutes||0)-(b.series[1]?.durationMinutes||0))-((a.series[0]?.durationMinutes||0)-(a.series[1]?.durationMinutes||0)))[0];
  const s=report.now.summary,items=[
    {label:'Largest contribution',title:top?.name||'No matching tickets',body:top?`${n(top.series[0]?.tickets)} ticket rows · ${hrs(top.series[0]?.durationMinutes)} restoration hrs`:'Choose another period or adjust the filters.'},
    {label:'Duration movement',title:worst?.name||'Comparison unavailable',body:worst?`${rate(worst.durationChange)} vs ${esc(report.prev.range?.label)}. Current: ${hrs(worst.series[0]?.durationMinutes)} hrs.`:'The comparison period is outside the source date range.'},
    {label:'District to review',title:districts[0]?.name||'No district data',body:districts[0]?`${n(districts[0].series[0]?.tickets)} tickets. ${n(s?.repeatSites)} COWs have repeated tickets in the review period.`:'No records in the selected scope.'}
  ];
  return `<section class="panel focus-panel"><div class="panel-title"><div><h2>Review priorities</h2><p>Selected period · ${esc(report.definition.impact)}</p></div><span class="focus-marker"></span></div><div class="focus-items">${items.map((x,i)=>`<div class="focus-item"><span class="focus-number">0${i+1}</span><div><small class="priority-label">${x.label}</small><h3>${esc(x.title)}</h3><p>${x.body}</p></div></div>`).join('')}</div></section>`;
}
function comparisonTable(report,field,title,limit=12){
  const visual=report.profile.visuals?.[field];
  const all=comparisonGroups(report,field),groups=all.slice(0,limit),drill={root_cause:'cause',region:'region',district:'district',site_label:'priority',severity:'severity',duration_bucket:'duration'}[field];
  const max=Math.max(1,...groups.flatMap(g=>g.series.map(s=>s?.tickets||0)));
  return `<section class="panel comparison-panel"><div class="panel-title"><div><h2>${esc(title)}</h2><p>${field==='duration_bucket'?'Duration bands from the decoded DAX column':'Ticket volume and restoration hours · same filters for every period'}</p></div><span class="section-count">${n(all.length)} ${field==='root_cause'?'causes':'groups'}</span></div><div class="data-table-wrap"><table class="comparison-table data-table"><thead><tr><th>${field==='duration_bucket'?'Recorded duration':field==='root_cause'?'Root cause':esc(title.replace(' comparison',''))}</th>${report.series.map((s,i)=>`<th class="right"><i class="series-dot" style="background:${colors[i]}"></i>${esc(s.range?.label||'Unavailable')}<small>Tickets / hours</small></th>`).join('')}<th class="right">TT change</th><th class="right">Hrs change</th></tr></thead><tbody>${groups.map(g=>`<tr><td>${drill?`<button class="table-link" data-${drill}="${esc(g.name)}">${esc(g.name)}</button>`:esc(g.name)}<div class="comparison-spark" aria-hidden="true">${g.series.map((s,i)=>`<i style="width:${(s?.tickets||0)/max*100}%;background:${colors[i]}"></i>`).join('')}</div></td>${g.series.map(s=>`<td class="right"><b>${n(s?.tickets)}</b><span class="subline">${hrs(s?.durationMinutes)} hrs</span></td>`).join('')}<td class="right">${rate(g.ticketChange)}</td><td class="right">${rate(g.durationChange)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No tickets match this page’s criteria.</td></tr>'}</tbody></table></div>${visual?`<p class="panel-foot">Saved visual filters apply to these groups; KPI totals and the register retain all page records. ${esc((visual.notes||[]).join(' '))}</p>`:''}${all.length>limit?`<details class="remaining-groups"><summary>View all ${n(all.length)} groups</summary><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Group</th><th>Review tickets</th><th>Review hrs</th><th>TT change</th></tr></thead><tbody>${all.slice(limit).map(g=>`<tr><td><button class="table-link" data-${drill}="${esc(g.name)}">${esc(g.name)}</button></td><td>${n(g.series[0]?.tickets)}</td><td>${hrs(g.series[0]?.durationMinutes)}</td><td>${rate(g.ticketChange)}</td></tr>`).join('')}</tbody></table></div></details>`:''}</section>`;
}
function tickets(report){const rows=report.now.rows.slice().sort((a,b)=>b.created_date.localeCompare(a.created_date)).slice(0,10);return `<section class="panel"><div class="panel-title"><div><h2>Ticket traceability</h2><p>Latest 10 records in the review period · every KPI can be traced to its source</p></div><button class="text-button" data-go="tickets">Open ticket register →</button></div><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Ticket / COW</th><th>Region / district</th><th>Created</th><th>Root cause</th><th class="right">Restoration hrs</th></tr></thead><tbody>${rows.map(r=>`<tr><td><button class="table-link" data-ticket="${esc(r.id)}">${esc(r.ticket_number)}</button><span class="subline">${esc(r.site_id)}</span></td><td>${esc(r.region)}<span class="subline">${esc(r.district)}</span></td><td>${date(r.created_date)}</td><td>${esc(r.root_cause)}</td><td class="right">${hrs(r.duration_minutes)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No matching source records.</td></tr>'}</tbody></table></div></section>`;}
function annualMatrix(report,state,meta){
  if(!['month-year','year','week-year'].includes(report.definition.mode))return '';
  const years=report.series.map(s=>s.range?.year),rows=Array.from({length:12},(_,i)=>{
    const m=String(i+1).padStart(2,'0');return {label:new Date(Date.UTC(2024,i,15)).toLocaleDateString('en-GB',{month:'short',timeZone:'UTC'}),values:years.map(year=>{
      const month=year+'-'+m,start=month+'-01',end=new Date(Date.UTC(year,i+1,0)).toISOString().slice(0,10);
      if(end<meta.min_date||start>meta.max_date)return null;
      const records=report.scope.filter(r=>r.created_date.slice(0,7)===month);
      return {tickets:records.length,minutes:records.reduce((n,r)=>n+(r.duration_minutes||0),0),partial:end>meta.max_date};
    })};
  });
  return `<section class="panel"><div class="panel-title"><div><h2>Year comparison by month</h2><p>Full monthly context under this page’s criteria · cells show tickets / hours</p></div><span class="section-count">${report.definition.impact}</span></div><div class="data-table-wrap"><table class="data-table annual-matrix"><thead><tr><th>Month</th>${years.map(y=>`<th class="right">${y||'—'}</th>`).join('')}</tr></thead><tbody>${rows.map(x=>`<tr><td>${x.label}</td>${x.values.map(v=>`<td class="right">${n(v?.tickets)}<span class="subline">${hrs(v?.minutes)} hrs${v?.partial?' · partial':''}</span></td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`;
}
export function renderReport(report,state,meta){
  const s=report.now.summary,p=report.prev.summary,reference='vs '+(report.prev.range?.label||'unavailable period');
  const changeValue=v=>num(v)?(v>0?'+':'')+n(v,1):'—';
  const missing=s?.missingDuration||0;
  return `<div class="section-heading"><div><h2>${esc(report.now.range?.label||'Period unavailable')}</h2><p>${esc(subtitle(report))}</p></div><span class="period-badge ${report.now.partial?'partial':''}">${report.now.partial?'Partial coverage':'Power BI criteria'}</span></div>${seriesHeader(report)}
  <div class="kpis">${card('Ticket volume',n(s?.tickets),'',report.ticketChange,reference,`COUNTROWS · ${n(s?.distinctTickets)} distinct ticket numbers`,true)}${card('Restoration duration',hrs(s?.durationMinutes),'hrs',report.durationChange,reference,`${n(s?.durationCount)} recorded durations · ${n(missing)} missing`)}${card('Ticket change',changeValue(report.ticketChange),num(report.ticketChange)?'%':'',null,report.definition.comparison,p?`${n(p.tickets)} comparison ticket rows`:'Comparison outside source coverage')}${card('Duration change',changeValue(report.durationChange),num(report.durationChange)?'%':'',null,report.definition.comparison,p?`${hrs(p.durationMinutes)} comparison hours`:'Comparison outside source coverage')}</div>
  <div class="report-metrics"><div><b>${n(s?.sites)}</b><span>COWs with tickets</span></div><div><b>${n(s?.repeatSites)}</b><span>COWs with 2+ tickets</span></div><div><b>${hrs(s?.mttr)} <small>hrs</small></b><span>Mean recorded restoration</span></div><div><b>${n(s?.slaCompliance,1)}<small>%</small></b><span>Source SLA compliance · ${n(s?.slaEligible)} eligible</span></div></div>
  ${report.now.partial||report.prev.partial?'<div class="report-coverage-note">The source does not cover every day in one or more displayed periods. Review the date ranges before interpreting the change.</div>':''}
  <div class="dashboard-grid">${trend(report,state,meta)}${focus(report)}</div>
  ${comparisonTable(report,'region','Regional comparison')}
  <div class="section-grid">${comparisonTable(report,'root_cause','Root cause comparison',8)}${comparisonTable(report,'district','District comparison',8)}</div>
  <div class="section-grid">${comparisonTable(report,'site_label','Site priority comparison')}${comparisonTable(report,'severity','Severity comparison')}</div>
  ${comparisonTable(report,'duration_bucket','Restoration duration distribution')}
  ${annualMatrix(report,state,meta)}${tickets(report)}
  <div class="report-basis"><b>Calculation basis</b><span>COUNTROWS after page filters. Recorded days × 1440 minutes; hours = minutes ÷ 60. Sunday-based weeks, with January 1 in week 1. Lower ticket volume and duration are shown in green. A new nonzero period against zero shows +100%; both zero shows 0%. Source SLA is separate from Power BI’s mislabeled change visual.</span><button class="text-button" data-go="formulas">Inspect formulas & criteria →</button></div>`;
}
export function renderFormulaAudit(audit,profiles){
  if(!audit)return '<section class="panel empty">Formula audit is unavailable. Reload the page to retry.</section>';
  if(audit.private)return `<section class="panel"><div class="panel-title"><div><h2>Power BI formula audit</h2><p>The complete extraction is available in the private review workspace.</p></div></div><div class="prose"><p>All five original report pages, 123 DAX measures, 88 calculated columns and 13 calculated tables were extracted. Original report metadata is kept with the private platform.</p><p><a class="button primary" href="https://stc-cow-performance-review.eng-altieb.chatgpt.site/#formulas">Open private formula audit</a></p><p>For a separate private deployment, run scripts/extract_powerbi.py on your PBIX and copy its generated formula-audit.json into dist.</p></div></section>`;
  return `<div class="audit-intro"><div><span class="eyebrow">POWER BI MODEL REVIEW</span><h2>From report logic to operational decisions</h2><p>Every original page and expression is recorded below. Live comparisons use selectable periods; legacy inconsistencies remain visible in this audit.</p></div><a class="button primary" href="formula-audit.json" download>Download full extraction</a></div><div class="report-metrics"><div><b>${audit.page_count}</b><span>Original report pages</span></div><div><b>${audit.measure_count}</b><span>DAX measures</span></div><div><b>${audit.calculated_column_count}</b><span>Calculated columns, including date tables</span></div><div><b>${audit.calculated_table_count}</b><span>Calculated tables</span></div></div>
  <section class="panel"><div class="panel-title"><div><h2>Page criteria</h2><p>SA and NSA scopes are kept separately, as saved in the report</p></div></div><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Dashboard</th><th>Service impact</th><th>Parent TT</th><th>Root cause exclusions</th><th>Comparison</th></tr></thead><tbody>${Object.entries(profiles).filter(([id])=>id!=='yoy').map(([id,p])=>`<tr><td><button class="table-link" data-go="${id}">${esc(p.name)}</button></td><td>${p.impact_mode==='NSA'?'Not Outage (includes Degraded)':'Outage'}</td><td>Blank</td><td><details><summary>${p.excluded_root_causes.length} saved values</summary><p class="exclusion-values">${p.excluded_root_causes.map(esc).join(' · ')||'No root cause exclusions'}</p></details></td><td>${esc({overview:'Review month vs previous two months','weekly-sa':'Review week vs previous two weeks','weekly-nsa':'Review week vs previous two weeks','mom-y':'Same month across three years','wow-y':'Same Sunday-based week across three years'}[id])}</td></tr>`).join('')}<tr><td>YoY (new)</td><td>Outage</td><td>Blank</td><td>Monthly SA exclusions</td><td>Matching YTD through review month</td></tr></tbody></table></div></section>
  <section class="panel audit-findings"><div class="panel-title"><div><h2>Model findings and live behavior</h2><p>These explain differences from the saved report; they are never silently applied as ticket exclusions.</p></div></div><ol>${audit.findings.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></section>
  ${audit.pages.map(page=>`<details class="panel audit-page"><summary><b>${esc(page.name)}</b><span>${page.visuals.length} visual containers · inspect visual queries and filters</span></summary>${page.visuals.filter(v=>v.select.length).map(v=>`<details class="audit-visual"><summary>${esc(v.title||v.type)} <small>${esc(v.type)}</small></summary><pre>${esc(JSON.stringify({select:v.select,where:v.where,visual_filters:v.visual_filters},null,2))}</pre></details>`).join('')}</details>`).join('')}
  <section class="panel"><div class="panel-title"><div><h2>Original DAX measures</h2><p>Exact expressions from the semantic model · legacy hard-coded names and dates retained</p></div></div>${audit.measures.map(m=>`<details class="audit-formula"><summary>${esc(m.Name)}</summary><pre>${esc(m.Expression)}</pre></details>`).join('')}</section>
  <section class="panel"><div class="panel-title"><div><h2>Calculated columns & tables</h2><p>Includes duration bands, SLA expressions and calendar definitions</p></div></div>${[...audit.calculated_columns,...audit.calculated_tables].map(m=>`<details class="audit-formula"><summary>${esc(m.TableName)}${m.ColumnName?' · '+esc(m.ColumnName):''}</summary><pre>${esc(m.Expression)}</pre></details>`).join('')}</section>
  <section class="panel"><div class="panel-title"><div><h2>Power Query transformations</h2><p>Source folder paths are redacted in this downloadable audit; transformations are preserved.</p></div></div>${audit.power_query.map(m=>`<details class="audit-formula"><summary>${esc(m.TableName)}</summary><pre>${esc(m.Expression)}</pre></details>`).join('')}</section>`;
}
